actions.script:
// This is a deliberately narrow self-service surface. Never accept a partyId,
// userId or organizationId from the request for these account-wide lists.
section = ['notifications', 'messages', 'calendar', 'tasks', 'account'].contains(section) ? section : 'account'
def partyId = ec.user.userAccount?.partyId
workspaceRows = []
workspaceError = false
try {
    if (section == 'notifications') {
        ec.entity.find('moqui.security.user.NotificationMessageByUser')
                .condition('userId', ec.user.userId).orderBy('-sentDate').limit(50).list().each { row ->
            workspaceRows.add([title:row.titleText ?: 'Notification', detail:'',
                    date:row.sentDate?.toString() ?: ''])
        }
    } else if (section == 'messages' && partyId) {
        def byId = [:]
        ['fromPartyId', 'toPartyId'].each { side ->
            ec.entity.find('mantle.party.communication.CommunicationEvent')
                    .condition(side, partyId).orderBy('-entryDate').limit(50).list().each { row ->
                byId[row.communicationEventId] = [title:row.subject ?: 'Message', detail:(row.body ?: '').toString().take(280),
                        date:row.entryDate?.toString() ?: '']
            }
        }
        workspaceRows = byId.values().sort { a, b -> b.date <=> a.date }.take(50)
    } else if ((section == 'calendar' || section == 'tasks') && partyId) {
        def query = ec.entity.find('mantle.work.effort.WorkEffortAndParty')
                .condition('partyId', partyId)
                .condition('workEffortTypeEnumId', section == 'tasks' ? 'WetTask' : 'WetEvent')
                .orderBy(section == 'tasks' ? '-estimatedCompletionDate' : '-estimatedStartDate').limit(50)
        query.list().each { row ->
            workspaceRows.add([title:row.workEffortName ?: (section == 'tasks' ? 'Task' : 'Event'),
                    detail:(row.description ?: '').toString().take(280),
                    date:(section == 'tasks' ? row.estimatedCompletionDate : row.estimatedStartDate)?.toString() ?: ''])
        }
    }
} catch (Exception ignored) {
    workspaceRows = []
    workspaceError = true
}
workspaceTitle = [notifications:'Notifications', messages:'Messages', calendar:'Calendar',
        tasks:'Tasks', account:'My Account'][section]
